const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {}; const h = item.headers || {};
const got = q.t || q.token || h['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Read-only audit of the live spreadsheet. Exists because the schema DOC has been wrong twice:
// source_config is documented as the product config but is really an arrival-channel dropdown,
// and channel_state_email is documented as not_sent/queued/sent but is really a pipeline-stage
// vocabulary. Guessing from the doc put invalid values into columns a human reads.
//
// Reports the headers each tab actually has, and the distinct values actually present in the
// columns that turned out to be dropdowns — the live sheet, not the documentation, is the truth.
const TABS = ["Leads", "Suppression", "Events", "Costs", "Segments", "Demo", "Inbox", "Pipeline", "System"];

// ⚠️ WHAT THIS CAN AND CANNOT SEE.
// The Sheets node returns one object per DATA row, keyed by the header row. So the header names
// are only visible when at least one data row exists. An empty tab is indistinguishable, from
// here, between "has a correct header row, no data yet" and "is completely blank".
//
// That is not a footnote: reporting `header_count: 0` for an empty tab is how a completely
// unprovisioned Inbox tab sat unnoticed while the mapper polled it every two minutes and found
// nothing (2026-08-29). This now says `unknown` rather than `0`, so the ambiguity is on the page
// instead of hidden behind a number that looks like a finding.
const out = {};
for (const tab of TABS) {
  let rows = [];
  try { rows = $(`Read ${tab}`).all().map((i) => i.json || {}); } catch (e) { rows = null; }
  if (rows === null) { out[tab] = { status: 'unreadable', note: 'no output from the read node' }; continue; }

  // A tab that does not exist comes back as a single item carrying an error, because every read
  // is onError:continueRegularOutput + alwaysOutputData. Do not report that as a column named
  // "error".
  const errored = rows.length === 1 && rows[0] && typeof rows[0].error !== 'undefined'
                  && Object.keys(rows[0]).filter((k) => k !== 'row_number').length === 1;
  if (errored) {
    // ⚠️ A FAILED READ IS NOT A MISSING TAB.
    //
    // This reported every failed read as 'missing'. Google Sheets allows 60 read requests per
    // minute per user, and this workflow alone spends nine of them; add two pollers and a person
    // pasting rows and the limit is reachable in normal use. Hit live 2026-08-30: six tabs that
    // demonstrably existed — including Inbox and System, written to minutes earlier — were all
    // reported as "no such tab", which sends someone hunting a deletion that never happened.
    //
    // A quota failure and a deleted tab need opposite responses (wait vs. re-provision), so they
    // must never share a label.
    const msg = String(rows[0].error && (rows[0].error.message || rows[0].error) || rows[0].error || '');
    const throttled = /quota|too many requests|rate limit|RESOURCE_EXHAUSTED|429/i.test(msg);
    out[tab] = throttled
      ? { status: 'throttled',
          note: 'the Google Sheets read quota was exceeded — this says NOTHING about whether the tab exists. Wait a minute and re-run.',
          error: msg.slice(0, 300) }
      : { status: 'missing',
          note: 'the read failed and it does not look like throttling — the tab may genuinely not exist',
          error: msg.slice(0, 300) };
    continue;
  }

  const real = rows.filter((r) => Object.keys(r).some((k) => k !== 'row_number' && String(r[k] ?? '').trim()));
  const headers = [...new Set(rows.flatMap((r) => Object.keys(r)))].filter((k) => k !== 'row_number');
  const vals = {};
  for (const col of headers) {
    const seen = [...new Set(real.map((r) => String(r[col] ?? '').trim()).filter(Boolean))];
    if (seen.length) vals[col] = seen.slice(0, 8);
  }

  if (real.length === 0) {
    out[tab] = {
      status: 'empty',
      header_count: 'unknown',
      headers: null,
      data_rows: 0,
      note: 'no data rows, so the header row cannot be read from here — write one row to confirm it',
    };
    continue;
  }
  out[tab] = { status: 'ok', header_count: headers.length, headers, data_rows: real.length, values: vals };
}
// A partial audit must announce itself. Reading nine tabs is this workflow's own biggest cost,
// so it is the most likely thing to trip the quota — and a half-read audit that looks complete is
// worse than one that failed outright.
const throttled = Object.keys(out).filter((t) => out[t].status === 'throttled');
if (throttled.length) {
  out._WARNING = `INCOMPLETE AUDIT — ${throttled.length} tab(s) could not be read because the ` +
    `Google Sheets per-minute read quota was exceeded: ${throttled.join(', ')}. ` +
    `Their real state is UNKNOWN from this run. Wait a minute and re-run.`;
}
return [{ json: out }];
